import { generateFoundation as generate } from './generate.mjs';
import { readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';

/** Connects Core's generated app types to the host compiler without manual imports. */
export async function generateFoundationHost(root) {
  await generate(root);
  const file = path.join(root, 'foundation-env.d.ts');
  const content =
    '// Generated by SaaS Foundation. Do not edit.\n/// <reference path="./.foundation/app.ts" />\n';
  if ((await readFile(file, 'utf8').catch(() => null)) !== content) await writeFile(file, content);
}
